import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Issue tracker","description":"GitHub issue commands and repository conventions","frontmatter":{"title":"Issue tracker","description":"GitHub issue commands and repository conventions","editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/agents/issue-tracker.md"},"headers":[],"relativePath":"docs/agents/issue-tracker.md","filePath":"docs/agents/issue-tracker.md","lastUpdated":1792252120000}`),a={name:`docs/agents/issue-tracker.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="issue-tracker-github" tabindex="-1">Issue tracker: GitHub <a class="header-anchor" href="#issue-tracker-github" aria-label="Permalink to “Issue tracker: GitHub”">​</a></h1><p>We track issues and specs as GitHub issues. Run the <code>gh</code> commands below from this clone; GitHub CLI infers the repository from <code>git remote -v</code>.</p><h2 id="create-and-update-issues" tabindex="-1">Create and update issues <a class="header-anchor" href="#create-and-update-issues" aria-label="Permalink to “Create and update issues”">​</a></h2><p>Use a public issue form from <code>.github/ISSUE_TEMPLATE/</code> when filing a report. Report security vulnerabilities through the private reporting link in the issue chooser, never in a public issue.</p><p>Before an issue enters triage, its form&#39;s required sections must be present and complete. If an issue doesn&#39;t match a form or is missing required sections, the Issue intake workflow removes <code>status: needs triage</code> and applies <code>status: needs info</code>. Edit the issue to add the missing headings and details. When a tracked issue is complete, the workflow removes <code>status: needs info</code> and restores <code>status: needs triage</code>. Upstream pin issues are exempt. The optional affected-component field does not add <code>area:*</code> labels; maintainers choose those during triage.</p><ul><li><strong>Create an issue:</strong> <code>gh issue create --title &quot;...&quot; --body &quot;...&quot;</code>. For a multi-line body, use a heredoc and include the required headings from the matching form so the workflow can validate it.</li><li><strong>Read an issue:</strong> <code>gh issue view &lt;number&gt; --json number,title,body,labels,comments</code>.</li><li><strong>List issues:</strong> <code>gh issue list --state open --json number,title,body,labels,comments --jq &#39;[.[] | {number, title, body, labels: [.labels[].name], comments: [.comments[].body]}]&#39;</code>. Add the appropriate <code>--label</code> and <code>--state</code> filters.</li><li><strong>Comment:</strong> <code>gh issue comment &lt;number&gt; --body &quot;...&quot;</code>.</li><li><strong>Add or remove labels:</strong> <code>gh issue edit &lt;number&gt; --add-label &quot;...&quot;</code> or <code>--remove-label &quot;...&quot;</code>.</li><li><strong>Close an issue with a comment:</strong> <code>gh issue close &lt;number&gt; --comment &quot;...&quot;</code>.</li></ul><p>To make one issue a child of another, use <code>gh issue create --parent &lt;parent&gt; ...</code> or run <code>gh issue edit &lt;parent&gt; --add-sub-issue &lt;child&gt;</code> afterwards (<code>gh</code> 2.94+). On an older <code>gh</code>, use <code>gh api --method POST repos/&lt;owner&gt;/&lt;repo&gt;/issues/&lt;parent&gt;/sub_issues -F sub_issue_id=&lt;child-db-id&gt;</code>; <code>&lt;child-db-id&gt;</code> is the child&#39;s database id. If GitHub sub-issues aren&#39;t available, put <code>Part of #&lt;parent&gt;</code> at the top of the child issue body.</p><h2 id="pull-requests-as-a-triage-surface" tabindex="-1">Pull requests as a triage surface <a class="header-anchor" href="#pull-requests-as-a-triage-surface" aria-label="Permalink to “Pull requests as a triage surface”">​</a></h2><p><strong>PRs as a request surface: no.</strong> <em>(Set this to <code>yes</code> if the repo treats external PRs as feature requests; <code>/triage</code> reads this flag.)</em></p><p>When this flag is <code>yes</code>, triage PRs with the <code>gh pr</code> equivalents:</p><ul><li><strong>Read a PR:</strong> <code>gh pr view &lt;number&gt; --comments</code> and <code>gh pr diff &lt;number&gt;</code>.</li><li><strong>List external PRs for triage:</strong> <code>gh api --paginate &#39;repos/{owner}/{repo}/pulls?state=open&#39; --jq &#39;.[] | select(.author_association | IN(&quot;OWNER&quot;,&quot;MEMBER&quot;,&quot;COLLABORATOR&quot;) | not) | {number, title, author: .user.login, author_association, labels: [.labels[].name]}&#39;</code>.</li><li><strong>Comment, label, or close:</strong> <code>gh pr comment</code>, <code>gh pr edit --add-label</code>/<code>--remove-label</code>, or <code>gh pr close</code>.</li></ul><p>GitHub uses one number space for issues and PRs, so <code>#42</code> alone is ambiguous. Check with <code>gh pr view 42</code>; if it isn&#39;t a PR, use <code>gh issue view 42</code>.</p><h2 id="instructions-referenced-by-other-skills" tabindex="-1">Instructions referenced by other skills <a class="header-anchor" href="#instructions-referenced-by-other-skills" aria-label="Permalink to “Instructions referenced by other skills”">​</a></h2><ul><li>When a skill says <strong>publish to the issue tracker</strong>, create a GitHub issue.</li><li>When a skill says <strong>fetch the relevant ticket</strong>, read it with <code>gh issue view &lt;number&gt; --json number,title,body,labels,comments</code>.</li></ul><h2 id="wayfinding-operations" tabindex="-1">Wayfinding operations <a class="header-anchor" href="#wayfinding-operations" aria-label="Permalink to “Wayfinding operations”">​</a></h2><p><code>/wayfinder</code> stores one map issue and its decision tickets in GitHub. Use the map&#39;s <code>wayfinder:map</code> label; link each ticket as a GitHub sub-issue. If sub-issues aren&#39;t enabled, add each child to a task list in the map body and put <code>Part of #&lt;map&gt;</code> at the top of the child body. Label each ticket <code>wayfinder:&lt;type&gt;</code> with one of <code>research</code>, <code>prototype</code>, <code>grilling</code>, or <code>task</code>. Once claimed, assign it to the developer driving the map.</p><p>The issue intake workflow currently recognizes only the public issue forms and exempts upstream-pin issues. It treats a new Wayfinder map or ticket without a matching form as an unmatched issue, removes <code>status: needs triage</code>, and adds <code>status: needs info</code>. The Wayfinder conventions do not provide an intake exemption, so expect this label behavior until the workflow supports these tickets.</p><h3 id="track-blockers-and-find-the-next-ticket" tabindex="-1">Track blockers and find the next ticket <a class="header-anchor" href="#track-blockers-and-find-the-next-ticket" aria-label="Permalink to “Track blockers and find the next ticket”">​</a></h3><p>Use GitHub&#39;s native issue dependencies when available; they appear in GitHub&#39;s UI. Add a blocking edge with:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --method</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos/</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">owne</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">rep</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/issues/</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">chil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dependencies/blocked_by</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> issue_id=</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">blocker-db-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><code>&lt;blocker-db-id&gt;</code> must be the blocker&#39;s numeric database id, not its issue number or <code>node_id</code>. Get it with <code>gh api repos/&lt;owner&gt;/&lt;repo&gt;/issues/&lt;n&gt; --jq .id</code>. GitHub reports the count of open blockers in <code>issue_dependencies_summary.blocked_by</code>. If native dependencies aren&#39;t available, write <code>Blocked by: #&lt;n&gt;, #&lt;n&gt;</code> at the top of the child body instead. A ticket is unblocked when all its blockers are closed.</p><p>To find the frontier, list the map&#39;s open child issues with <code>gh issue list --state open</code>, scoped to the map&#39;s sub-issues or task list. Skip tickets with an open blocker (<code>issue_dependencies_summary.blocked_by &gt; 0</code>, or an open issue in a <code>Blocked by</code> line) and tickets that already have an assignee. The first remaining ticket in map order is next.</p><p>Claim it with <code>gh issue edit &lt;n&gt; --add-assignee @me</code> before doing any work; this assignment must be the session&#39;s first write.</p><h3 id="resolve-a-ticket" tabindex="-1">Resolve a ticket <a class="header-anchor" href="#resolve-a-ticket" aria-label="Permalink to “Resolve a ticket”">​</a></h3><p>Post the answer as a comment with <code>gh issue comment &lt;n&gt; --body &quot;&lt;answer&gt;&quot;</code>, close the ticket with <code>gh issue close &lt;n&gt;</code>, then append a context pointer (gist and link) to the map&#39;s <code>Decisions so far</code> section.</p>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};